insert into public.families (slug, name, code, position, intro, seo, biocide) values ('absorbants', 'Absorbants', 'ABS', 1, 'Fuite d''huile, liquide renversé, verglas : ce qui se ramasse vite et ne glisse plus.', '["Une flaque d''huile sur un quai, du gasoil sur la voirie après un accident, un liquide organique dans un couloir d''école : l''absorbant doit agir tout de suite et se ramasser proprement. La gamme MCI couvre les trois cas. SUPER GRANUL est un absorbant lourd et inerte, antidérapant, homologué SETRA pour la chaussée ; SUPER GRANUL FEUILLE est un textile qui capte les hydrocarbures sans absorber l''eau, pour les bacs de rétention et les zones portuaires ; ALO solidifie et désodorise les liquides organiques avant le ramassage.","Le DÉVERGLAÇANT complète la famille pour les accès piétons en hiver : parvis de mairie, rampes, escaliers d''établissements scolaires. Il existe aussi en version liquide.","Pour les services techniques de Sète, Frontignan, Balaruc ou de la métropole de Montpellier, une organisation simple : un seau dans chaque véhicule d''intervention, un sac au dépôt. Commandez en seau de 10 kg pour les véhicules, en sac de 20 kg pour le stock : MCI confirme les conditionnements disponibles à la validation."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('aerosols', 'Aérosols', 'AÉRO', 2, 'Dégrippants, graisses, lubrifiants, nettoyants et insecticides en boîtier : l''atelier dans une caisse.', '["L''aérosol, c''est le produit qu''on a sur soi : dans la caisse du mécanicien, sur l''établi de l''atelier municipal, dans le coffre du technicien de maintenance. La gamme MCI en compte une trentaine, classés par usage. Pour la mécanique : CST (super dégrippant, anti-humidité, existe en version bio et PTFE), GHT pour les assemblages chauds, LUBRAXEL et LUBRAXONE pour les graisses, TARAUXYL pour le perçage et le taraudage, GRAPHITEX pour les freins.","Pour le milieu alimentaire, BRILLANTEUR INOX, GRALIXONE et LUBRIXAL sont identifiés contact alimentaire. Pour l''électricité, DIELEC30 nettoie sans solvant chloré. Pour les nuisibles, OXYCHOC traite les nids de guêpes et de frelons asiatiques à distance, MCI AXADRINE les punaises et la gale, INSECTICIDE BIO les volants et rampants à l''huile essentielle.","Les aérosols se commandent par carton de 12. Dans le bassin de Thau, où l''air salin attaque tout ce qui est métallique, un dégrippant et une graisse adhérente font partie du stock de base des ateliers nautiques et des services techniques."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('decapants-detartrants', 'Décapants – Détartrants', 'DÉC', 3, 'Tartre, rouille, graisses cuites, tags, mousses : ce qui ne part pas avec un nettoyant ordinaire.', '["Cette famille regroupe les produits qui attaquent une salissure précise. Le tartre des circuits et échangeurs (DETARCIRC, DAS 30 avec indicateur de saturation), les dépôts de vin rouge dans les cuves (REDOX associé au PEROXYL), la rouille sur l''inox (MP50), l''oxydation de l''aluminium (NETALU / NETINOX), la laitance de ciment (DÉCABÉTON), les graisses cuites des cuisines collectives (DG90).","Pour l''espace public, DETAG décape les graffitis sur surfaces sensibles, en bidon ou en lingettes pour les interventions rapides en tournée. KERMEX désincruste algues vertes, mousses et moisissures sur toitures, murs et terrasses. Pour les sanitaires, SANIKEL RENFORCÉ assure l''entretien quotidien, SANITARTRE la remise en état, SANIBIO18 l''entretien aux enzymes.","Les caves coopératives et domaines de l''Hérault utilisent NPV pour les pulvérisateurs et REDOX NF, à contact alimentaire, pour le matériel de cave. Chaque produit a sa fiche technique : lisez-la avant la première utilisation, les dilutions varient selon la salissure."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('detergents-desinfectants', 'Détergents – Désinfectants', 'DÉT', 4, 'Nettoyer et désinfecter les surfaces, la plonge, les sols sportifs et les zones alimentaires.', '["Un détergent enlève la salissure, un désinfectant détruit les micro-organismes : beaucoup de produits de cette famille font les deux en une étape. STERSOL (plusieurs parfums) et BAM4 sont des détergents désinfectants de qualité alimentaire, adaptés aux cantines et cuisines collectives. STÉRI MCI est fongicide, virucide et sporicide à contact alimentaire, pour les laboratoires et l''agroalimentaire. ECODYL désinfecte en prêt à l''emploi avec une formule 100 % végétale.","Pour les usages ciblés : DDA pour les sols de gymnase, STÉRIBAC pour la plonge, DMOUSSE pour le nettoyage mousse en atelier de production, DSF34 et DSF34 BIO pour les fontaines de dégraissage, BIONAL pour les WC chimiques des camping-cars et bateaux.","Écoles, gymnases, EHPAD, cuisines centrales : entre Sète, Mèze et Montpellier, les collectivités ont besoin d''une fiche technique et d''une fiche de données de sécurité pour chaque référence. Les désinfectants sont des biocides : respectez les dosages de la fiche technique."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('desherbants-insecticides-biocides', 'Désherbants – Insecticides – Biocides', 'BIO-C', 5, 'Fourmis, blattes, rongeurs, guêpes et frelons, adventices : traiter, appâter, protéger.', '["Les nuisibles se traitent avec le bon mode d''application. Appâts en seringue pour les fourmis (DOBOL) et les blattes (FORCEGEL ULTRA), compatibles pistolet applicateur ; appât en poudre FOURMICYL pour l''extérieur ; laque rémanente INSECTILAC pour les cafards ; raticides et souricides RTS 45 et RTS PÂTE livrés avec boîtes appâts. En aérosol : OXYCHOC pour les nids de guêpes et de frelons asiatiques, MCI AXADRINE pour les puces, punaises et acariens, MCI ANTI-RONGEUR pour protéger câbles et gaines.","Côté désherbage, SPEED est un désherbant total foliaire de biocontrôle, prêt à l''emploi : une réponse pour les communes qui entretiennent trottoirs, cimetières et cours d''école sans produits phytosanitaires de synthèse.","Campings de la côte héraultaise, cuisines collectives, services techniques municipaux : chaque intervention doit être tracée. Téléchargez la fiche technique avant l''achat et demandez la fiche de données de sécurité à MCI si elle n''est pas en ligne."]'::jsonb, true) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('surodorants-shampooings', 'Surodorants – Shampooings', 'SUR', 6, 'Odeurs, lavage des véhicules, linge, vaisselle : l''entretien courant, bien dosé.', '["Cette famille couvre l''entretien courant qui se voit et se sent. Contre les odeurs : FLORALÈNE (destructeur d''odeurs), GELODOR (gel prêt à l''emploi pour sanitaires et locaux poubelles), FLORALIES (surodorant détergent désinfectant, plusieurs parfums). Pour les surfaces : MULTIPLUS et MULTISPRAY, à contact alimentaire, MAXFLASH en mousse.","Pour les véhicules et les bateaux : NET CAR dégraisse sans solvant, SHAMCAR laisse une action déperlante, STATCAR convient aux portiques et stations de lavage. NPV, polyvalent, nettoie aussi les pulvérisateurs agricoles et viticoles.","Pour le linge et la vaisselle : LESSIVE LINGE, tous textiles en machine, et MCI LAVE-VAISSELLE formulé pour les eaux extra-dures, un vrai sujet sur le littoral héraultais où l''eau est très calcaire."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('produits-bio', 'Produits bio', 'BIO', 7, 'Enzymes, bactéries, bases végétales : entretenir sans chimie lourde là où c''est possible.', '["Les produits de cette famille travaillent avec des enzymes, des bactéries ou des matières premières végétales. ACTIFOSSE relance l''activité biologique des fosses septiques et microstations, fréquentes dans l''arrière-pays héraultais et les campings. MCIBIO 02 entretient les bacs à graisse et les canalisations de cuisine. DÉSOBIO10 supprime les odeurs à la source dans les sanitaires, sur les moquettes et la voirie.","BIOSOLV dégraisse et dégoudronne avec une formule 100 % végétale ; BIONET nettoie les mains très sales à l''atelier. SANIBIO18 entretient les sanitaires aux enzymes acides, BIONAL traite les WC chimiques et toilettes en circuit fermé, INSECTICIDE BIO agit à l''huile essentielle.","Un produit biologique a besoin de temps de contact et de régularité pour être efficace : les fiches techniques précisent le dosage et la fréquence. Pour une démarche plus large (établissement labellisé, camping engagé), appelez MCI : on construit la sélection avec vous."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('peintures-savons-solvants', 'Peintures – Savons – Solvants', 'PSS', 8, 'Gamme sur demande : dites-nous ce que vous cherchez.', '["Peintures de marquage, savons d''atelier, solvants de nettoyage : MCI fournit ces produits sur demande, en fonction de l''usage et du volume. La gamme n''est pas encore détaillée en ligne.","Décrivez votre besoin (surface, quantité, contrainte réglementaire) ou appelez le 04 48 08 45 89 : un interlocuteur à Sète vous répond et vous envoie la fiche technique du produit proposé."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.families (slug, name, code, position, intro, seo, biocide) values ('produits-specifiques', 'Produits spécifiques', 'SPÉ', 9, 'Un besoin hors catalogue ? MCI cherche le produit avec vous.', '["Traitement particulier, contrainte de site, produit utilisé ailleurs qu''on ne trouve plus : MCI étudie les demandes spécifiques des professionnels et des collectivités.","Décrivez la surface, la salissure ou le nuisible, et les contraintes (contact alimentaire, milieu naturel, public sensible). On vous rappelle avec une proposition et sa fiche technique."]'::jsonb, false) on conflict (slug) do update set name = excluded.name, code = excluded.code, position = excluded.position, intro = excluded.intro, seo = excluded.seo, biocide = excluded.biocide;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('mairies', 'Mairies', 'administrations', 'Services techniques, voirie, espaces verts, bâtiments communaux.', 'Un tag sur la façade de l''école lundi matin, une flaque de gasoil au rond-point, des mousses sur le monument aux morts, du verglas sur le parvis : les services techniques interviennent vite, avec peu de produits, et doivent justifier chaque achat par un bon d''engagement.', '["Pour les communes et métropoles, MCI regroupe les produits d''intervention de voirie et d''entretien du patrimoine : DETAG en bidon, en aérosol et en lingettes pour les graffitis, KERMEX contre les mousses et algues vertes, SUPER GRANUL (homologué SETRA) pour les hydrocarbures sur chaussée, DÉVERGLAÇANT pour les accès piétons, SPEED pour le désherbage en biocontrôle, OXYCHOC pour les nids de frelons asiatiques signalés par les habitants.","Le bon de commande en ligne accepte votre numéro d''engagement et la facturation via Chorus Pro (code service). Un agent peut préparer la commande, un valideur la confirmer : l''option se règle par compte.","MCI est installé au Parc Aquatechnique de Sète, à quelques minutes des services techniques du bassin de Thau ; zone et délai de livraison sont confirmés à chaque commande. Pour une commande récurrente, créez un compte pro et enregistrez vos listes : « Stock voirie », « Hiver », « Graffitis »."]'::jsonb, 1) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('ecoles-universites', 'Écoles & universités', 'administrations', 'Agents d''entretien, intendance, gestionnaires de lycées et de campus.', 'Sanitaires utilisés par des centaines d''élèves, tables de cantine désinfectées entre deux services, blattes dans une cuisine de lycée : il faut des produits efficaces, des fiches de sécurité à jour et zéro odeur agressive dans les salles.', '["Écoles, collèges, lycées et universités ont les mêmes points chauds : sanitaires, restauration, surfaces de contact. SANIKEL RENFORCÉ détartre et désodorise au quotidien, STERSOL et ECODYL désinfectent les surfaces (ECODYL en prêt à l''emploi, formule végétale), DG90 dégraisse les hottes et fours des cuisines, FORCEGEL ULTRA traite les blattes en appât sans pulvérisation dans les locaux.","Chaque fiche produit donne accès à la fiche technique ; demandez la fiche de données de sécurité depuis la fiche si elle n''est pas en ligne. Les intendances peuvent indiquer leur numéro de bon de commande et facturer via Chorus Pro.","Pour la rentrée, enregistrez une liste favorite « Rentrée scolaire » dans votre espace pro et recommandez-la en un clic chaque année. MCI confirme disponibilité et délai de livraison pour chaque commande, depuis Sète."]'::jsonb, 2) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('equipements-sportifs', 'Équipements sportifs', 'administrations', 'Gestionnaires de gymnases, piscines, stades et complexes sportifs.', 'Un sol de gymnase qui glisse après lavage, des vestiaires qui sentent malgré le ménage, des mousses sur les gradins extérieurs : les équipements sportifs combinent sols techniques, humidité et forte fréquentation.', '["DDA est un détergent agréé alimentaire formulé pour les sols de gymnase, utilisable en autolaveuse. Pour les vestiaires et douches : SANIKEL RENFORCÉ pour le tartre, STERSOL pour la désinfection, DÉSOBIO10 et GELODOR pour les odeurs. KERMEX traite les mousses et moisissures sur les gradins et abords, LESSIVE LINGE entretient chasubles et serviettes.","Complexes sportifs municipaux, salles intercommunales, stades de Sète à Montpellier : le bon de commande accepte les numéros d''engagement et la facturation Chorus Pro. Conditionnements en 5 L et 20 L pour les autolaveuses, confirmés par MCI à la validation."]'::jsonb, 3) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('viticulture', 'Viticulture', 'industries', 'Chefs de cave, caves coopératives, domaines, entreprises de travaux viticoles.', 'Après les vendanges, les cuves sont rouges de tartre et de matière colorante, les pulvérisateurs gardent des résidus de traitement, et tout ce qui touche le vin doit être rincé et compatible contact alimentaire.', '["Le dérougissage des cuves se fait en deux temps : REDOX, nettoyant dérougissant très puissant, puis PEROXYL, oxygène actif qui désinfecte sans chlore et sans odeur. REDOX NF, super dégraissant à contact alimentaire, s''occupe du matériel de cave et de récolte. DETARCIRC et DAS 30 (avec indicateur de saturation) détartrent les circuits et échangeurs.","Pour le matériel de traitement, NPV désincruste les résidus phytosanitaires, la chlorophylle et les colles des cuves et rampes de pulvérisateurs. KERMEX nettoie les abords, murs et toitures des chais.","Du Picpoul de Pinet aux caves de l''arrière-pays héraultais, la sélection part de Sète. Ajoutez la sélection au bon de commande, ajustez les conditionnements (5 L ou 20 L) et indiquez vos contraintes d''accès (quai, horaires de cave)."]'::jsonb, 4) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('agriculture', 'Agriculture', 'industries', 'Exploitations, CUMA, négoces, ateliers de matériel agricole.', 'Pulvérisateurs à rincer entre deux produits, engins à graisser, fuites d''huile dans le hangar, rongeurs dans les réserves : l''exploitation a besoin de peu de références, mais des bonnes.', '["NPV nettoie les pulvérisateurs agricoles et désincruste les résidus phytosanitaires. REDOX NF dégraisse le matériel à contact alimentaire. En atelier : CST dégrippe et protège de l''humidité, LUBRAXEL graisse roulements et articulations (existe en cartouche). SUPER GRANUL et SUPER GRANUL FEUILLE absorbent les fuites d''huile et d''hydrocarbures, RTS 45 traite rats et souris avec boîtes appâts fournies, SPEED désherbe les cours et abords en biocontrôle.","Les CUMA et négoces de l''Hérault peuvent créer un compte pro multi-utilisateurs : chaque adhérent prépare sa commande, un responsable la valide. Les fiches techniques sont téléchargeables avant l''achat."]'::jsonb, 5) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('biotechnologie', 'Biotechnologie', 'industries', 'Laboratoires, salles propres, unités de production agroalimentaire et biotech.', 'Surfaces à désinfecter avec un spectre large (bactéries, levures, virus, spores), circuits à détartrer sans contaminer, inox à garder impeccable : chaque produit doit avoir une fiche technique et une FDS à jour pour le dossier qualité.', '["STÉRI MCI est fongicide, virucide et sporicide, à contact alimentaire (existe en prêt à l''emploi). ECODYL désinfecte avec une formule 100 % végétale. BAM4 et DMOUSSE combinent détergence et désinfection, DMOUSSE en nettoyage mousse. DAS 30 nettoie les circuits avec un indicateur de saturation, PEROXYL désinfecte à l''oxygène actif sans chlore. APN33NF et ACINOL RENFORCÉ entretiennent l''inox et les métaux nobles.","MCI est installé au Parc Aquatechnique de Sète, zone d''activités tournée vers la mer et les biotechnologies. Demandez les FDS depuis chaque fiche, commandez avec votre numéro de bon de commande interne."]'::jsonb, 6) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('automobile', 'Automobile', 'industries', 'Garages, carrosseries, flottes de véhicules, stations de lavage.', 'Freins à dégraisser sans laisser de film, fontaine de dégraissage à recharger, carrosseries à laver sans traces, mains noires en fin de journée : l''atelier consomme vite et commande souvent les mêmes références.', '["GRAPHITEX dégraisse disques et plaquettes de frein sans solvant chloré, séchage ultra-rapide. DSF34 et DSF34 BIO alimentent les fontaines de dégraissage en phase aqueuse. NET CAR dégraisse sans solvant, SHAMCAR (déperlant) et STATCAR (film statique) lavent les carrosseries, y compris en portique. LUBRAXEL graisse, BIONET nettoie les mains.","Garages de Sète, Frontignan, Balaruc et de la métropole de Montpellier : utilisez la commande rapide par référence (« GRAPHITEX;CARTON-12;2 ») et enregistrez votre liste « Stock atelier » pour recommander en un clic."]'::jsonb, 7) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('campings', 'Campings', 'loisirs', 'Gérants et équipes d''entretien d''hôtellerie de plein air, villages vacances.', 'En juillet, les blocs sanitaires tournent jour et nuit, les bornes de vidange des camping-cars débordent, un nid de frelons apparaît près de la piscine et la fosse septique sature : tout doit être en stock avant la saison.', '["SANIKEL RENFORCÉ assure l''entretien quotidien des blocs sanitaires, SANITARTRE la remise en état avant ouverture. BIONAL traite les WC chimiques des camping-cars et les toilettes en circuit fermé, DÉSOBIO10 supprime les odeurs à la source, ACTIFOSSE relance les fosses septiques. OXYCHOC traite les nids de guêpes et frelons à distance, FORCEGEL ULTRA les blattes des cuisines de snack, LESSIVE LINGE le linge des locatifs.","Sur la côte héraultaise, de Marseillan à Vias et de Frontignan à Palavas, le stock doit être en place avant l''ouverture. Préparez votre liste « Ouverture saison » dans l''espace pro, indiquez les créneaux et contraintes d''accès (portail, horaires d''accueil) : MCI confirme disponibilité et délai."]'::jsonb, 8) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.sectors (slug, name, grp, buyer, problem, seo, position) values ('nautisme', 'Nautisme', 'loisirs', 'Chantiers navals, ports de plaisance, loueurs, ateliers de mécanique marine.', 'Le sel grippe les manilles, l''aluminium s''oxyde, l''inox rouille en surface, les WC marins sentent, une fuite de gasoil apparaît dans un bassin : le nautisme cumule mécanique, carrosserie et environnement sensible.', '["CST dégrippe et protège de l''humidité et de la corrosion (existe en version bio à l''huile végétale), TARAUXYL sert au perçage et au taraudage. NETALU / NETINOX désoxyde et rénove aluminium et inox, MP50 dérouille l''inox, BRILLANTEUR INOX finit l''accastillage. SHAMCAR lave coques et superstructures avec une action déperlante. BIONAL traite les WC marins en circuit fermé, SUPER GRANUL FEUILLE capte les hydrocarbures sans absorber l''eau.","Sète est un port de pêche, de commerce et de plaisance : les chantiers de la zone portuaire, du canal et de l''étang de Thau sont nos voisins. Commandez par référence, faites livrer au chantier ou au port, avec vos contraintes d''accès."]'::jsonb, 9) on conflict (slug) do update set name = excluded.name, grp = excluded.grp, buyer = excluded.buyer, problem = excluded.problem, seo = excluded.seo, position = excluded.position;
insert into public.products (id, slug, code, short, description, families, sectors, properties, formats, container, packagings, usages, variants, instructions, dilution, technical_sheet_url, sds_url, image_url, related, to_confirm, admin_note, active, featured, position) values ('p-alo', 'alo', 'ALO', 'Absorbant liquides organiques', 'Absorbant solidifiant et désodorisant pour liquides organiques.', array['absorbants']::text[], '{}'::text[], '{}'::text[], array['poudre']::text[], 'bucket', '[{"id":"10kg","label":"Seau 10 kg","short":"10 KG","container":"bucket"},{"id":"20kg","label":"Sac 20 kg","short":"20 KG","container":"bucket"}]'::jsonb, array['Vomissures et liquides organiques','Solidification avant ramassage','Désodorisation']::text[], null, null, null, 'https://a8e9cf56-40bd-492b-b9b4-d4dcc7eca13a.usrfiles.com/ugd/5f3c99_ecaa4a6f8ef8464a808c566986d7ae41.pdf', null, null, array['super-granul']::text[], array['packagings','properties','sectors','instructions','dilution','usages','sdsUrl']::text[], null, true, false, 0) on conflict (id) do nothing;
